<?php
/** @var array{css:?string,js:?string} $assets */
/** @var array<int,array<string,string>> $navigation */
/** @var array<string,string> $period */
/** @var array<string,mixed> $report */
$money = static fn (float $value): string => ($value < 0 ? '−' : '') . '$' . number_format(abs($value), 2);
$query = static function (string $sort, string $defaultDirection = 'desc') use ($period, $report): string {
    $direction = $report['sort'] === $sort ? ($report['direction'] === 'desc' ? 'asc' : 'desc') : $defaultDirection;
    return '?' . http_build_query(['period' => $period['preset'], 'from' => $period['from'], 'to' => $period['to_inclusive'], 'sort' => $sort, 'direction' => $direction]);
};
$detailQuery = http_build_query(['period' => $period['preset'], 'from' => $period['from'], 'to' => $period['to_inclusive']]);
?>
